mapper.select:
SELECT email
  FROM members
 WHERE name = #{name}
   AND birth_date = #{birthDate}
   AND REPLACE(phone, '-', '') = #{phone}
   AND status = 'ACTIVE'
 ORDER BY created_at DESC, id DESC

SELECT id, email
  FROM members
 WHERE email = #{email}
   AND name = #{name}
   AND birth_date = #{birthDate}
   AND REPLACE(phone, '-', '') = #{phone}
   AND status = 'ACTIVE'
   AND password IS NOT NULL

mapper.update:
UPDATE members
name = #{name}, nickname = #{nickname}, phone = #{phone}, password = #{password},
WHERE id = #{id}

UPDATE members
   SET password = #{password}
 WHERE id = #{id}
   AND status = 'ACTIVE'
   AND password IS NOT NULL

UPDATE members
   SET status = #{status},
       withdrawn_at = CURRENT_TIMESTAMP(6)
 WHERE id = #{id}
   AND status != #{status}
